/* Generated by equipe-design emit — do not edit by hand; change the tokens and emit again. */
@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));

@theme {
  /* colour roles: bg-background, text-text, border-border … */
  --color-background: #ffffff;
  --color-surface: #f6f6f6;
  --color-raised: #fafafa;
  --color-text: #000000;
  --color-muted-text: #616161;
  --color-primary: #0000cc;
  --color-on-primary: #ffffff;
  --color-secondary: #ffdd00;
  --color-accent: #b00020;
  --color-border: #c7c7c7;
  --color-border-strong: #737373;
  --color-ring: #0000cc;
  --color-destructive: #c62828;
  --color-success: #1b7a43;
  --color-warning: #8f5b00;

  /* palette: bg-teal-600 … (the step is lightness, 0 light to 1000 dark) */
  --color-neutral-0: #ffffff;
  --color-neutral-25: #f6f6f6;
  --color-neutral-50: #fafafa;
  --color-neutral-175: #c7c7c7;
  --color-neutral-300: #9e9e9e;
  --color-neutral-350: #8c8c8c;
  --color-neutral-450: #737373;
  --color-neutral-500: #616161;
  --color-neutral-650: #383838;
  --color-neutral-750: #222222;
  --color-neutral-775: #1a1a1a;
  --color-neutral-850: #0d0d0d;
  --color-neutral-975: #000000;
  --color-yellow-100: #ffdd00;
  --color-yellow-200: #e8b44a;
  --color-yellow-475: #8f5b00;
  --color-blue-200: #66ccff;
  --color-blue-625: #0000cc;
  --color-orange-275: #ff7b72;
  --color-orange-450: #c62828;
  --color-green-275: #4cc38a;
  --color-green-500: #1b7a43;
  --color-red-525: #b00020;

  /* fonts */
  --font-sans: 'Atkinson Hyperlegible', Pretendard, 'Noto Sans KR', sans-serif;
  --font-mono: 'JetBrains Mono', ui-monospace, monospace;

  /* radius */
  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 6px;
  --radius-full: 9999px;

  /* type roles: text-body, text-h1 … */
  --text-display: 55px;
  --text-display--line-height: 1.25;
  --text-display--letter-spacing: 0em;
  --text-display--font-weight: 700;
  --text-h1: 44px;
  --text-h1--line-height: 1.25;
  --text-h1--letter-spacing: 0em;
  --text-h1--font-weight: 700;
  --text-h2: 35px;
  --text-h2--line-height: 1.25;
  --text-h2--letter-spacing: 0em;
  --text-h2--font-weight: 700;
  --text-h3: 28px;
  --text-h3--line-height: 1.25;
  --text-h3--letter-spacing: 0em;
  --text-h3--font-weight: 700;
  --text-body: 18px;
  --text-body--line-height: 1.6;
  --text-body--letter-spacing: 0em;
  --text-body--font-weight: 400;
  --text-small: 14px;
  --text-small--line-height: 1.6;
  --text-small--letter-spacing: 0em;
  --text-small--font-weight: 400;
  --text-mono: 14px;
  --text-mono--line-height: 1.6;
  --text-mono--letter-spacing: 0em;
  --text-mono--font-weight: 400;

  /* motion */
  --duration-fast: 0ms;
  --duration-base: 80ms;
  --duration-slow: 120ms;
  --ease-standard: cubic-bezier(0, 0, 1, 1);
}

.dark {
  --color-background: #000000;
  --color-surface: #0d0d0d;
  --color-raised: #1a1a1a;
  --color-text: #ffffff;
  --color-muted-text: #9e9e9e;
  --color-primary: #ffdd00;
  --color-on-primary: #000000;
  --color-secondary: #222222;
  --color-accent: #66ccff;
  --color-border: #383838;
  --color-border-strong: #8c8c8c;
  --color-ring: #ffdd00;
  --color-destructive: #ff7b72;
  --color-success: #4cc38a;
  --color-warning: #e8b44a;
}
